import{assert}from"chrome://resources/js/assert.js";import{fakeFirmwareUpdates}from"./fake_data.js";import{FakeUpdateController}from"./fake_update_controller.js";import{FakeUpdateProvider}from"./fake_update_provider.js";import{InstallController,UpdateProvider}from"./firmware_update.mojom-webui.js";let useFakeProviders=false;let updateProvider=null;let updateController=null;export function setUseFakeProviders(value){useFakeProviders=value}export function setUpdateProviderForTesting(testProvider){updateProvider=testProvider}export function setUpdateControllerForTesting(testUpdateController){updateController=testUpdateController}function setupFakeUpdateProvider(){const provider=new FakeUpdateProvider;provider.setFakeFirmwareUpdates(fakeFirmwareUpdates);setUpdateProviderForTesting(provider)}function setupFakeUpdateController(){setUpdateControllerForTesting(new FakeUpdateController)}export function getUpdateProvider(){if(!updateProvider){if(useFakeProviders){setupFakeUpdateProvider()}else{updateProvider=UpdateProvider.getRemote()}}assert(!!updateProvider);return updateProvider}export function getUpdateController(){if(!updateController){if(useFakeProviders){setupFakeUpdateController()}else{updateController=InstallController.getRemote()}}assert(!!updateController);return updateController}